menus = env['website.menu'] base_domain = [('website_id', '=', website.id)] top_menu = menus.search(base_domain + [('parent_id', '=', False)], limit=1) pos_config = env.ref('takeaway_restaurant.pos_config_1') menus.search(base_domain + [('url', 'in', ['/shop', '/event', '/appointment'])]).unlink()
